export function generateReport(rows) {
  const lines = []
  for (const r of rows) {
    const d = new Date(r.date)
    const day = `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, '0')}-${String(d.getUTCDate()).padStart(2, '0')}`
    const amount = (r.cents / 100).toFixed(2)
    lines.push(`${day}  ${r.label.padEnd(10)} ${amount.padStart(9)}`)
  }
  const total = (rows.reduce((s, r) => s + r.cents, 0) / 100).toFixed(2)
  lines.push(`TOTAL${' '.repeat(18)}${total.padStart(9)}`)
  return lines.join('\n')
}

