import { test } from 'node:test'
import assert from 'node:assert'
import { generateReport } from '../src/report.js'

test('formats rows and total', () => {
  const out = generateReport([
    { date: '2024-03-05T10:00:00Z', label: 'Coffee', cents: 450 },
    { date: '2024-03-06T10:00:00Z', label: 'Lunch', cents: 1299 }
  ])
  assert.equal(out.split('\n').length, 3)
  assert.match(out, /2024-03-05  Coffee\s+4\.50/)
  assert.match(out, /TOTAL\s+17\.49$/)
})

