def shipping_cost(weight_kg, country, express=False):
    if country == "SE":
        if weight_kg <= 1:
            if express:
                return 99
            else:
                return 49
        else:
            if express:
                return 149
            else:
                return 79
    else:
        if country in ("NO", "DK", "FI"):
            if weight_kg <= 1:
                return 129 if express else 69
            else:
                return 199 if express else 109
        else:
            raise ValueError("unsupported country")

