import pytest

from pricing import shipping_cost


@pytest.mark.parametrize("w,c,e,expected", [
    (1, "SE", False, 49), (1, "SE", True, 99), (2, "SE", False, 79), (2, "SE", True, 149),
    (1, "NO", False, 69), (1, "DK", True, 129), (3, "FI", False, 109), (3, "FI", True, 199),
])
def test_costs(w, c, e, expected):
    assert shipping_cost(w, c, e) == expected


def test_unsupported():
    with pytest.raises(ValueError):
        shipping_cost(1, "US")

